import React from 'react';
import ReadyOrders from './ReadyOrders';

const Dashboard = () => {
  return (
    <div className="fullscreen-dashboard bg-white text-black">
      {/* Header */}
      <header className="bg-black text-white p-4 shadow-lg">
        <h1 className="text-2xl font-bold">Ready Orders Display</h1>
        <p className="text-sm text-gray-300 mt-1">Live order status - Read Only</p>
      </header>

      {/* Main Content Area - Ready Orders Only */}
      <main className="flex-1 p-6 overflow-auto">
        <ReadyOrders />
      </main>

      {/* Footer */}
      <footer className="bg-black text-white p-4 mt-auto">
        <div className="flex justify-between items-center">
          <span className="text-sm text-gray-300">© 2024 Canteen TV Dashboard</span>
          <span className="text-sm text-gray-300">Version 1.0.0</span>
        </div>
      </footer>
    </div>
  );
};

export default Dashboard;
